import { NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";

const prisma = new PrismaClient();

export async function POST(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || !session.user.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { flagId, status, reviewComment } = await request.json();

    if (!flagId || !status || !reviewComment) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Validate flag exists
    const flag = await prisma.flag.findUnique({
      where: { id: flagId },
    });

    if (!flag) {
      return NextResponse.json(
        { error: "Flag not found" },
        { status: 404 }
      );
    }

    // Check if a review already exists for this flag by this reviewer
    const existingReview = await prisma.flag.findFirst({
      where: {
        id: flagId,
        reviewComment: { not: null },
      },
    });

    let review;
    if (existingReview) {
      // Update existing review
      review = await prisma.flag.update({
        where: { id: flagId },
        data: {
          reviewComment,
          status: status === "approved" ? "RESOLVED" : status === "rejected" ? "DISMISSED" : "IN_REVIEW",
          resolvedBy: session.user.id,
          resolvedAt: status === "approved" || status === "rejected" ? new Date() : null,
        },
      });
    } else {
      // Create new review by updating the flag
      review = await prisma.flag.update({
        where: { id: flagId },
        data: {
          reviewComment,
          status: status === "approved" ? "RESOLVED" : status === "rejected" ? "DISMISSED" : "IN_REVIEW",
          resolvedBy: session.user.id,
          resolvedAt: status === "approved" || status === "rejected" ? new Date() : null,
        },
      });
    }

    return NextResponse.json({
      success: true,
      review: {
        id: flagId,
        flagId,
        reviewerId: session.user.id,
        status,
        comment: reviewComment,
        createdAt: review.updatedAt,
      },
    });
  } catch (error) {
    console.error("Error in flag-reviews POST:", error);
    return NextResponse.json(
      { error: "Failed to submit flag review" },
      { status: 500 }
    );
  } finally {
    await prisma.$disconnect();
  }
}

export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user || !session.user.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const pdfId = searchParams.get("pdfId");

    if (!pdfId) {
      return NextResponse.json(
        { error: "Missing pdfId" },
        { status: 400 }
      );
    }

    // Fetch flags with reviews for the given PDF
    const flags = await prisma.flag.findMany({
      where: {
        pdfId,
        reviewComment: { not: null },
      },
      select: {
        id: true,
        reviewComment: true,
        status: true,
        updatedAt: true,
        resolvedBy: true,
      },
    });

    const reviews = flags.map((flag) => ({
      id: flag.id,
      flagId: flag.id,
      reviewerId: flag.resolvedBy || "",
      status:
        flag.status === "RESOLVED"
          ? "approved"
          : flag.status === "DISMISSED"
          ? "rejected"
          : "needs_clarification",
      comment: flag.reviewComment || "",
      createdAt: flag.updatedAt,
    }));

    return NextResponse.json({
      success: true,
      reviews,
    });
  } catch (error) {
    console.error("Error in flag-reviews GET:", error);
    return NextResponse.json(
      { error: "Failed to fetch flag reviews" },
      { status: 500 }
    );
  } finally {
    await prisma.$disconnect();
  }
}